<?php require_once __DIR__.'/../app/bootstrap.php';$id=(int)($_GET['id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){require_login();verify_csrf();if(user()['status']!=='active')exit('Cuenta no habilitada');$body=trim($_POST['body']??'');if($body!==''){db()->prepare('INSERT INTO comments(post_id,user_id,body) VALUES(?,?,?)')->execute([$id,user()['id'],$body]);}redirect('post.php?id='.$id);} $q=db()->prepare("SELECT p.*,u.username,pr.display_name,pr.avatar FROM posts p JOIN users u ON u.id=p.user_id JOIN profiles pr ON pr.user_id=u.id WHERE p.id=? AND p.status='published'");$q->execute([$id]);$p=$q->fetch();if(!$p)exit('Publicación no encontrada');$q=db()->prepare("SELECT c.*,u.username,pr.display_name,pr.avatar FROM comments c JOIN users u ON u.id=c.user_id JOIN profiles pr ON pr.user_id=u.id WHERE c.post_id=? AND c.status='published' ORDER BY c.created_at");$q->execute([$id]);$comments=$q->fetchAll();require __DIR__.'/../partials/header.php';?><section><article class="card post"><div class="author"><img src="<?=url($p['avatar']?:'assets/img-avatar.svg')?>"><strong><?=e($p['display_name'])?></strong></div><h1><?=e($p['title'])?></h1><p><?=nl2br(e($p['body']))?></p><?php if($p['image']):?><img class="post-image" src="<?=url($p['image'])?>"><?php endif;?></article><div class="card"><h2>Comentarios</h2><?php foreach($comments as $c):?><div class="comment"><strong><?=e($c['display_name'])?></strong><p><?=nl2br(e($c['body']))?></p></div><?php endforeach;?><?php if(user()):?><form method="post"><?=csrf_field()?><textarea name="body" required maxlength="1500" placeholder="Escribe un comentario"></textarea><button class="btn">Comentar</button></form><?php endif;?></div></section><?php require __DIR__.'/../partials/footer.php';?>
